import {GatewayClient} from '<CHECKOUT>/src/gateway/client.ts';
import {captureRuntimeConfigAsyncReader} from '<CHECKOUT>/src/config/config.ts';
import {resolveGatewayClientBootstrap} from '<CHECKOUT>/src/gateway/client-bootstrap.ts';
import {resolveDeviceIdentityForGatewayCall} from '<CHECKOUT>/src/gateway/call-device-auth.ts';
import {chromium} from '<CHECKOUT>/node_modules/playwright/index.mjs';
const cfg=await captureRuntimeConfigAsyncReader()();
const b=await resolveGatewayClientBootstrap({config:cfg,ignoreEnvUrlOverride:true,localPortOverride:23429,suppressEnvAuthFallback:true});
const identity=await resolveDeviceIdentityForGatewayCall('read-only');
const key='agent:main:proof-grounding-'+crypto.randomUUID();
const ready=Promise.withResolvers<void>();let voiceSessionId:string|undefined;let browser:any;
const gw=new GatewayClient({url:b.url,...b.auth,deviceIdentity:identity??undefined,clientName:'gateway-client',clientDisplayName:'Grounding client-owned proof',mode:'backend',role:'operator',scopes:['operator.admin','operator.read','operator.write','operator.talk'],onHelloOk:()=>ready.resolve(),onConnectError:e=>ready.reject(e)});
const deadline=setTimeout(()=>{console.log('DEADLINE');gw.stop();process.exit(2)},90000);
try{gw.start();await ready.promise;console.log('CONNECTED');
const r:any=await gw.request('talk.client.create',{sessionKey:key,mode:'realtime',transport:'webrtc',brain:'agent-consult',provider:'openai',model:'gpt-live-1-codex',capabilities:['voice-transcript'],silenceDurationMs:400});voiceSessionId=r.voiceSessionId;
console.log('ADMITTED',JSON.stringify({provider:r.provider,transport:r.transport,voiceSessionPresent:!!voiceSessionId,clientControl:r.clientControl??'client-owned'}));
browser=await chromium.launch({headless:true});const page=await browser.newPage();
const offer=await page.evaluate(async()=>{const peer=new RTCPeerConnection();(globalThis as any).peer=peer;(globalThis as any).events=[];peer.addTransceiver('audio',{direction:'sendrecv'});const dc=peer.createDataChannel('oai-events');dc.onmessage=e=>{try{(globalThis as any).events.push(JSON.parse(e.data))}catch{}};const o=await peer.createOffer();await peer.setLocalDescription(o);if(peer.iceGatheringState!=='complete')await new Promise<void>(resolve=>{const t=setTimeout(resolve,8000);peer.addEventListener('icegatheringstatechange',()=>{if(peer.iceGatheringState==='complete'){clearTimeout(t);resolve()}})});return peer.localDescription!.sdp});
const offerUrl=new URL(r.offerUrl,'http://127.0.0.1:23429');
const response=await fetch(offerUrl,{method:'POST',headers:{Authorization:'Bearer '+r.clientSecret,'Content-Type':'application/sdp'},body:offer});console.log('BROKER_STATUS',response.status);const answer=await response.text();if(!response.ok)throw Error('Offer rejected '+response.status+' '+answer.slice(0,1200));
await page.evaluate(async(s:string)=>{await (globalThis as any).peer.setRemoteDescription({type:'answer',sdp:s})},answer);
await page.waitForFunction(()=>((globalThis as any).events??[]).some((e:any)=>e.type==='session.created'||e.type==='session.updated'||e.type==='session.started'),undefined,{timeout:20000}).catch(async e=>{console.log('TRANSPORT_DIAGNOSTIC',JSON.stringify(await page.evaluate(()=>({connectionState:(globalThis as any).peer.connectionState,iceState:(globalThis as any).peer.iceConnectionState,events:(globalThis as any).events}))));throw e});
const result=await page.evaluate(()=>{const p=(globalThis as any).peer;const e=(globalThis as any).events.find((e:any)=>(e.type==='session.created'||e.type==='session.updated'||e.type==='session.started'));return{connectionState:p.connectionState,eventType:e.type,session:e.session}});
const instructions=JSON.stringify(result.session);const groundingPresent=instructions.includes('Do not invent acknowledgments or progress claims.');const hostOnlyPolicyAbsent=!instructions.includes('Wait for the host control result before answering each new request');
console.log('PROVIDER_SESSION',JSON.stringify({connectionState:result.connectionState,eventType:result.eventType,groundingPresent,hostOnlyPolicyAbsent,instructions:result.session.instructions}));console.log('REAL_CLIENT_CONNECTED_PROVIDER_SESSION');
}finally{if(voiceSessionId)await gw.request('talk.client.close',{sessionKey:key,voiceSessionId}).then(()=>console.log('VOICE_CLOSED')).catch(e=>console.log('CLOSE_ERROR',e.message));if(browser)await browser.close();await gw.request('sessions.delete',{key,deleteTranscript:true}).then(()=>console.log('SESSION_DELETED')).catch(e=>console.log('DELETE_ERROR',e.message));gw.stop();clearTimeout(deadline)}

