const expression=process.argv[2]==='read'?"JSON.stringify((globalThis.__groundingProof??[]).map(({instructions,...r})=>({...r,instructionBytes:Buffer.byteLength(instructions),instructionSha256:process.getBuiltinModule('crypto').createHash('sha256').update(instructions).digest('hex'),groundingInstruction:instructions.split('\\n').find(s=>s.includes('Do not invent acknowledgments or progress claims.'))})))":`(()=>{globalThis.__groundingProof=[];const original=globalThis.fetch;globalThis.fetch=async function(url,init){let record;try{const body=typeof init?.body==='string'?JSON.parse(init.body):null;if(body?.session&&body?.sdp){const instructions=body.session.instructions??'';record={groundingPresent:instructions.includes('Do not invent acknowledgments or progress claims.'),hostOnlyPolicyAbsent:!instructions.includes('Wait for the host control result before answering each new request'),instructions};globalThis.__groundingProof.push(record)}}catch{}const response=await original.apply(this,arguments);if(record)record.providerStatus=response.status;return response};return 'INSTALLED_TEST_ONLY_FETCH_OBSERVER'})()`;
const result=await new Promise(resolve=>{ws.onmessage=e=>{const v=JSON.parse(e.data);if(v.id===1)resolve(v)};ws.send(JSON.stringify({id:1,method:'Runtime.evaluate',params:{expression,returnByValue:true}}))});console.log(JSON.stringify(result));ws.close();
